import{_ as u,a0 as l,w as a,s as r,I as e,x as s,a1 as n,A as o,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"如何創建 Ubuntu 持久化立付 U 盤 | LCTT x X-CMD","titleTemplate":false,"description":"如何創建 Ubuntu 持久化立付 U 盤 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何創建 Ubuntu 持久化立付 U 盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何創建 Ubuntu 持久化立付 U 盤 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230905 How to Create Persistent Live USB of Ubuntu","title":"如何創建 Ubuntu 持久化立付 U 盤","tag":"202309","desc":""},"relativePath":"202309/20230905 How to Create Persistent Live USB of Ubuntu.md","filePath":"[post].md"}'),d={name:"202309/20230905 How to Create Persistent Live USB of Ubuntu.md"};function b(m,t,g,f,U,h){const i=l("Link");return a(),r("div",null,[t[27]||(t[27]=e("h1",{id:"如何創建-ubuntu-持久化立付-u-盤",tabindex:"-1"},[s("如何創建 Ubuntu 持久化立付 U 盤 "),e("a",{class:"header-anchor",href:"#如何創建-ubuntu-持久化立付-u-盤","aria-label":"Permalink to “如何創建 Ubuntu 持久化立付 U 盤”"},"​")],-1)),t[28]||(t[28]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202309/06/162606ivjl1zoohb1h8vuo.jpg",alt:""})],-1)),t[29]||(t[29]=e("blockquote",null,[e("p",null,"體驗帶有持久化的立付 U 盤，你在立付會話中做出的所有改動都會被保存。在此教程中，你將學習如何創建一個持久化的 U 盤。")],-1)),t[30]||(t[30]=e("p",null,"如果我告訴你，你能將完整的 Ubuntu 系統裝載在一個可移動的 U 盤上，你會有何感想？",-1)),e("p",null,[t[1]||(t[1]=s("在外置 U 盤上 ",-1)),n(i,{href:"https://itsfoss.com/intsall-ubuntu-on-usb/"},{default:o(()=>[...t[0]||(t[0]=[s("安裝 Ubuntu",-1)])]),_:1}),t[2]||(t[2]=s(" 過程相當複雜。一種更容易的方法是製作一個帶有持久化存儲的 ",-1)),t[3]||(t[3]=e("ruby",null,[s("立付"),e("rt",null,"Live")],-1)),t[4]||(t[4]=s(" U 盤，這樣你對 U 盤做出的改動都會被保存下來。",-1))]),e("p",null,[t[6]||(t[6]=s("請相信我，這個過程跟使用 ",-1)),n(i,{href:"https://itsfoss.com/install-etcher-linux/"},{default:o(()=>[...t[5]||(t[5]=[s("BalenaEtcher",-1)])]),_:1}),t[7]||(t[7]=s(" 或其他任何刻錄工具創建可引導驅動器的過程十分相似。",-1))]),t[31]||(t[31]=p('<p>然而，我們在開始之前，讓我們先弄清楚持久化立付 U 盤是什麼。</p><h3 id="什麼是持久化立付-u-盤" tabindex="-1">什麼是持久化立付 U 盤？ <a class="header-anchor" href="#什麼是持久化立付-u-盤" aria-label="Permalink to “什麼是持久化立付 U 盤？”">​</a></h3><p>當你使用立付 Linux U 盤時，你在 <ruby>立付會話<rt>Live session</rt></ruby> 中做出的所有更改，在重啓以後都將丟失。比如，你必須重新連接 Wi-Fi，並且你下載的文件及安裝的應用均不會被保留。而持久化立付 U 盤將會為你保存這些所有的更改。</p><p>這樣，你就可以將該 U 盤作為一個外置操作系統使用，它將會保存你所做出的所有更改，比如創建用户賬號，安裝軟件包，和一切你通常在電腦上做的事情。</p><p>當然，保存的文件數量將取決於你使用的 U 盤的大小！</p><p>但你已經明白我要表達的意思了吧。那麼，我們開始學習如何創建一個帶有持久性的 Ubuntu 立付 U 盤吧。</p><h3 id="如何創建一個持久化的-ubuntu-u-盤" tabindex="-1">如何創建一個持久化的 Ubuntu U 盤 <a class="header-anchor" href="#如何創建一個持久化的-ubuntu-u-盤" aria-label="Permalink to “如何創建一個持久化的 Ubuntu U 盤”">​</a></h3><p>在這個教程中，我將引導你完成一個持久化的 Ubuntu U 盤的製作過程：</p><ul><li>通過在 Windows 上的 Rufus 工具</li><li>或者，通過在 Linux 上的 mkusb 工具</li></ul><p>你可以參照教程中的適合你的部分。</p><blockquote><p>📋 本教程中，你將會創建一個 Ubuntu 的持久化 U 盤。並非所有的 Linux 發行版都支持數據的持久化存儲，所以這個方法可能並非所有的發行版本適用。</p></blockquote><h3 id="方法-1-在-windows-上創建持久化的-ubuntu-u-盤" tabindex="-1">方法 1：在 Windows 上創建持久化的 Ubuntu U 盤 <a class="header-anchor" href="#方法-1-在-windows-上創建持久化的-ubuntu-u-盤" aria-label="Permalink to “方法 1：在 Windows 上創建持久化的 Ubuntu U 盤”">​</a></h3><p>在 Windows 上創建一個持久化的 Ubuntu U 盤，我會使用 Rufus，這是一款自由開源工具，專門用於將 ISO 文件刻錄到 U 盤上。</p>',13)),e("p",null,[t[9]||(t[9]=s("請訪問 ",-1)),n(i,{href:"https://rufus.ie/en/"},{default:o(()=>[...t[8]||(t[8]=[s("Rufus 的官方下載頁面",-1)])]),_:1}),t[10]||(t[10]=s("，獲取 Windows 版本的可執行文件：",-1))]),t[32]||(t[32]=p('<p><img src="https://itsfoss.com/content/images/2023/09/Download-Rufus-to-create-persistant-Ubuntu-drive-in-Windows.png" alt=""></p><p>然後，打開 Rufus，它將要求以管理員身份運行；請授予該權限，因為你即將在外部驅動器上做改動，需要相應的權限。</p><p>接下來，根據以下步驟使用 Rufus 創建持久化 U 盤：</p><ul><li>選中 U 盤設備（如果只有一個 U 盤，它將默認被選中）。</li><li>點擊 “<ruby>選擇<rt>Select</rt></ruby>” 按鈕，在文件管理器中選擇 ISO 文件。</li><li>你可以使用滑塊或直接設定持久化分區的大小（可以放心地設定為最大值）。</li><li>其他選項保持默認設置（除非你清楚在做什麼）。</li><li>點擊 “<ruby>開始<rt>Start</rt></ruby>” 按鈕，開始進行刻錄。</li></ul><p><img src="https://itsfoss.com/content/images/2023/09/Use-rufus-to-create-Ubuntu-persistant-drive.png" alt=""></p><p>該程序你會告訴你，選中的驅動器上的所有數據將會被刪除，所以你可以放心忽略這個警告。</p><p>完成後，我們可以來瞧瞧如何在 Windows 中直接啓動到 UEFI 設置。</p><h4 id="通過-u-盤啓動-簡化版" tabindex="-1">通過 U 盤啓動（簡化版） <a class="header-anchor" href="#通過-u-盤啓動-簡化版" aria-label="Permalink to “通過 U 盤啓動（簡化版）”">​</a></h4><p>這個方法應適用於大多數用户，如果無效，你總是可以選擇傳統的方式，那就是重新啓動系統並按下 <code>Esc</code>、<code>Delete</code>、<code>F1</code>、<code>F2</code>、<code>F10</code>、<code>F11</code> 或 <code>F12</code> 等按鍵。</p><p>步驟如下：按 <code>Win + X</code>，然後以管理員身份啓動 Windows PowerShell：</p><p><img src="https://itsfoss.com/content/images/2023/09/Start-Windows-powershell-as-admin.png" alt=""></p><p>一旦你看見提示符，直接運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shutdown.exe /r /fw</span></span></code></pre></div><p>這將會計劃一個關機動作，稍後，你會進入到 UEFI 固件設置。</p><p>到了這步，選擇 U 盤作為首選的啓動選項並保存設置：</p><p><img src="https://itsfoss.com/content/images/2023/09/Boot-from-UEFI-1.jpg" alt=""></p><p>你會看到一個正常的 GRUB 屏幕：</p><p><img src="https://itsfoss.com/content/images/2023/09/Boot-from-persisted-storage-USB-drive-made-using-Rufus-on-Windows-machine.png" alt=""></p><p>當你啓動後，選擇試用 Ubuntu 的選項，然後你所做的任何改動都可以被保存下來，即使你重新啓動了電腦也無所謂。</p><h3 id="方法-2-在-ubuntu-linux-上創建持久化-ubuntu-u-盤" tabindex="-1">方法 2：在 Ubuntu Linux 上創建持久化 Ubuntu U 盤 <a class="header-anchor" href="#方法-2-在-ubuntu-linux-上創建持久化-ubuntu-u-盤" aria-label="Permalink to “方法 2：在 Ubuntu Linux 上創建持久化 Ubuntu U 盤”">​</a></h3><blockquote><p>🚧 請注意，這種方法主要適用於 Ubuntu 和 Debian 的 ISO。</p></blockquote><p>如果你還不知道，<code>mkusb</code> 是一個帶有 GUI 的工具，讓你能夠將 ISO 文件刷到磁盤驅動器上，並且有附加功能，例如在 Ubuntu 上創建持久化驅動器。</p><p>你需要添加 <code>mkusb</code> 的 PPA 來進行安裝，具體命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:mkusb/ppa</span></span></code></pre></div><p>要使改變生效，需要更新軟件庫索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>最後，安裝 <code>mkusb</code> 以及其他相關軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install --install-recommends mkusb mkusb-nox usb-pack-efi</span></span></code></pre></div><p>就這樣！</p><p>首先，從系統菜單啓動 <code>mkusb</code> 工具，它會提示你輸入超級用户密碼：</p><p><img src="https://itsfoss.com/content/images/2023/08/Start-mkusb-tool-from-system-menu.png" alt=""></p><p>操作完成後，它會提示你所有驅動器上的數據將會被新數據覆蓋。</p><p>只需簡單地點擊 “OK” 按鈕即可：</p><p><img src="https://itsfoss.com/content/images/2023/08/Data-will-be-wiped-warning-.png" alt=""></p><p>然後它會顯示 <code>mkusb</code> 工具能執行的多項操作，你需要選擇第一選項 “<ruby>安裝（製作一個啓動設備）<rt>Install (make a boot device)</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-the-first-option-in-mkusb-tool-to-create-persistent-USB-drive-of-Ubuntu.png" alt=""></p><p>接下來，它會顯示許多安裝選項，你需要選擇第三個選項 “<ruby>持久化立付（僅針對 Debian 和 Ubuntu）<rt>&#39;Persistent live&#39; - only Debian and Ubuntu</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-the-persistent-option.png" alt=""></p><p>在下一個步驟中，它會讓你在多種方法/工具中選擇一個，如果沒有使用特定類型的版本，例如超精簡版本，建議使用第一個名為 “dus-Iso2usb” 的方法：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-the-grub-option.png" alt=""></p><p>接着，它會讓你從文件管理器中選擇你需要的 ISO 文件：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-an-ISO-file-to-create-persistent-USB-from-Ubuntu.png" alt=""></p><p>工具會顯示已選 ISO 文件的名稱，以及創建持久化 U 盤所要使用的工具：</p><p><img src="https://itsfoss.com/content/images/2023/08/Showing-seelcted-ISO-file.png" alt=""></p><p>下一步，你需要選擇驅動器將之前選擇的 ISO 文件刷入：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-drive-to-create-persistent-drive.png" alt=""></p><p>以上全部完成後，將會有 3 個選項供你選擇。如果你不確定使用哪一個，那麼就點擊 “<ruby>使用默認<rt>Use defaults</rt></ruby>” 按鈕，但是大多數用户選擇第二個選項 “grold” 即可（我也是選擇這個）：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-bootloader.png" alt=""></p><p>檢查一切都無誤後，點擊 “<ruby>開始<rt>Go</rt></ruby>” 開始刷新過程：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-go-ahead-option-in-mkusb-to-create-persistent-USB-drive.png" alt=""></p><p>現在，刷入過程已經開始了！</p><p><img src="https://itsfoss.com/content/images/2023/08/Flashing-process-to-make-persistent-usb-of-Ubuntu.png" alt=""></p><p><strong>注意，這個刷入過程會比你使用 BalenaEtcher 刷入要長一些時間！</strong></p><p>完成後，會有通知告訴你，過程已經完成，此時你可以取下 U 盤，然後重新插上，以查看更改的內容：</p><p><img src="https://itsfoss.com/content/images/2023/08/Persistent-drive-has-been-made.png" alt=""></p><h4 id="從持久化-u-盤啓動" tabindex="-1">從持久化 U 盤啓動 <a class="header-anchor" href="#從持久化-u-盤啓動" aria-label="Permalink to “從持久化 U 盤啓動”">​</a></h4><p>如果你要從 U 盤啓動，通常可以重啓你的系統，連續按下對應的按鈕即可，但這已經是舊方法了！</p><p>在 Linux 中，有一種更為簡便的方式訪問 BIOS，你只需在終端執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl reboot --firmware-setup</span></span></code></pre></div><p>然後，進入啓動菜單並將 U 盤設置為首選的啓動選項：</p><p><img src="https://itsfoss.com/content/images/2023/09/Boot-from-UEFI.jpg" alt=""></p><p>一旦你從 U 盤啓動，你將有兩個選項：</p><ul><li>帶有持久化模式的 ISO</li><li>以實時模式進行啓動</li></ul><p>如其名，你需要選擇第一個選項以啓動進入 Ubuntu 的持久化模式：</p><p><img src="https://itsfoss.com/content/images/2023/08/Boot-from-persisted-storage-USB-drive.png" alt=""></p>',65)),e("p",null,[t[12]||(t[12]=s("現在，你可以進行各種修改，如安裝你喜歡的軟件包，",-1)),n(i,{href:"https://learnubuntu.com/add-delete-users/"},{default:o(()=>[...t[11]||(t[11]=[s("創建新用户",-1)])]),_:1}),t[13]||(t[13]=s(" 等等！",-1))]),t[33]||(t[33]=e("p",null,"我希望這個指南對你有所幫助。",-1)),t[34]||(t[34]=e("p",null,[e("em",null,"（題圖：MJ/423c72d6-d6eb-4146-acd5-1e58eed11f41）")],-1)),t[35]||(t[35]=e("hr",null,null,-1)),e("p",null,[t[15]||(t[15]=s("via: ",-1)),n(i,{href:"https://itsfoss.com/ubuntu-persistent-live-usb/"},{default:o(()=>[...t[14]||(t[14]=[s("https://itsfoss.com/ubuntu-persistent-live-usb/",-1)])]),_:1})]),e("p",null,[t[19]||(t[19]=s("作者：",-1)),n(i,{href:"https://itsfoss.com/author/sagar/"},{default:o(()=>[...t[16]||(t[16]=[s("Sagar Sharma",-1)])]),_:1}),t[20]||(t[20]=s(" 選題：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[17]||(t[17]=[s("lujun9972",-1)])]),_:1}),t[21]||(t[21]=s(" 譯者：ChatGPT 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[18]||(t[18]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[24]||(t[24]=s("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[22]||(t[22]=[s("LCTT",-1)])]),_:1}),t[25]||(t[25]=s(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:o(()=>[...t[23]||(t[23]=[s("Linux中國",-1)])]),_:1}),t[26]||(t[26]=s(" 榮譽推出",-1))])])}const x=u(d,[["render",b]]);export{S as __pageData,x as default};
